import glob

rows = []
for path in glob.glob("loans/*.csv"):
    with open(path, encoding="utf-8") as f:
        next(f)
        for line in f:
            rows.append(line.strip().split(","))
rows.sort(key=lambda row: row[1])
for title, reader, due in rows:
    print(due, title, reader)
